                        <svg viewBox="0 0 24 24" fill="none"><path d="M4 5h16v14H4V5Zm0 1 8 7 8-7" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>
                        <input id="identifier" name="identifier" type="text" inputmode="email" autocomplete="username" placeholder="مثلاً ۰۹۱۲۱۲۳۴۵۶۷" aria-describedby="identifier-error">
                    </div>
                    <span class="error-text" id="identifier-error">شماره موبایل یا ایمیل خود را وارد کنید.</span>
                </div>

                <div class="field" id="password-field">
                    <div class="field-head"><label for="password">رمز عبور</label><button class="forgot" type="button" id="forgot-button">رمز عبور را فراموش کرده‌اید؟</button></div>
                    <div class="input-wrap">
                        <svg viewBox="0 0 24 24" fill="none"><rect x="4" y="10" width="16" height="11" rx="2" stroke="currentColor" stroke-width="1.6"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
                        <input id="password" name="password" type="password" autocomplete="current-password" placeholder="رمز عبور خود را وارد کنید" aria-describedby="password-error">
                        <button class="password-toggle" id="password-toggle" type="button" aria-label="نمایش رمز عبور">
                            <svg class="eye" viewBox="0 0 24 24" fill="none"><path d="M3 12s3-6 9-6 9 6 9 6-3 6-9 6-9-6-9-6Z" stroke="currentColor" stroke-width="1.6"/><circle cx="12" cy="12" r="2.5" stroke="currentColor" stroke-width="1.6"/></svg>
                            <svg class="eye-off" viewBox="0 0 24 24" fill="none"><path d="m4 4 16 16M10.5 6.2c.5-.13 1-.2 1.5-.2 6 0 9 6 9 6a14 14 0 0 1-2.3 3.2M7 7.8C4.3 9.4 3 12 3 12s3 6 9 6c1.1 0 2.1-.2 3-.5M9.9 9.9a3 3 0 0 0 4.2 4.2" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
                        </button>
                    </div>
                    <span class="error-text" id="password-error">رمز عبور خود را وارد کنید.</span>
                </div>

                <div class="form-options">
                    <label class="remember"><input type="checkbox" name="remember">مرا به خاطر بسپار</label>
                    <span class="security-note"><svg viewBox="0 0 24 24" fill="none"><path d="M12 21s7-3 7-9V5l-7-2-7 2v7c0 6 7 9 7 9Z" stroke="currentColor" stroke-width="1.7"/><path d="m9 12 2 2 4-5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>ورود امن و رمزنگاری‌شده</span>
                </div>

                <button class="submit-btn" id="submit-button" type="submit"><span>ورود به پورتال مشتریان</span><svg viewBox="0 0 24 24" fill="none"><path d="M19 12H5m6 6-6-6 6-6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><i class="spinner"></i></button>
            </form>
            <div class="support"><svg viewBox="0 0 24 24" fill="none"><path d="M4 13a8 8 0 0 1 16 0v5a2 2 0 0 1-2 2h-2v-7h4M4 13v7H2a2 2 0 0 1-2-2v-5h4Z" stroke="currentColor" stroke-width="1.6"/></svg>برای ورود به راهنمایی نیاز دارید؟ <a href="<?php echo e(route('home')); ?>#contact">ارتباط با پشتیبانی</a></div>
        </div>
    </section>

    <aside class="visual-side" aria-label="معرفی پورتال مشتریان سپند">
        <div class="visual-inner">
            <div class="visual-copy"><span class="visual-kicker">مدیریت شفاف در تمام مسیر</span><h2>محموله‌های شما،<br><span>همیشه در دسترس شما</span></h2><p>درخواست‌ها، اسناد و آخرین وضعیت عملیات را در یک نمای ساده و یکپارچه دنبال کنید.</p></div>
            <div class="shipment-card">
                <div class="shipment-head"><div class="shipment-id"><span class="shipment-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M4 17V9l8-5 8 5v8l-8 5-8-5Z" stroke="currentColor" stroke-width="1.6"/><path d="m4 9 8 5 8-5M12 14v8" stroke="currentColor" stroke-width="1.6"/></svg></span><span><strong>محموله فعال شما</strong><small>آخرین وضعیت عملیات حمل</small></span></div><span class="live"><i></i>به‌روزرسانی زنده</span></div>
                <div class="route-box"><div class="route-line"></div><div class="route-progress"></div><div class="route-nodes"><div class="route-node done"><span class="node-dot"><svg viewBox="0 0 24 24" fill="none"><path d="M4 17V9l8-5 8 5v8l-8 5-8-5Z" stroke="currentColor" stroke-width="1.6"/></svg></span><span><strong>ثبت سفارش</strong><br>تکمیل شده</span></div><div class="route-node done"><span class="node-dot"><svg viewBox="0 0 24 24" fill="none"><path d="M3 15h13V6H7L3 10v5Zm13-6h3l2 3v3h-5V9Z" stroke="currentColor" stroke-width="1.6"/><circle cx="7" cy="17" r="2" stroke="currentColor" stroke-width="1.6"/><circle cx="18" cy="17" r="2" stroke="currentColor" stroke-width="1.6"/></svg></span><span><strong>در مسیر</strong><br>در حال انجام</span></div><div class="route-node"><span class="node-dot"><svg viewBox="0 0 24 24" fill="none"><path d="M5 20V8h14v12M3 20h18M8 8V4h8v4" stroke="currentColor" stroke-width="1.6"/></svg></span><span><strong>تحویل</strong><br>مرحله بعد</span></div></div></div>
                <div class="shipment-stats"><div class="shipment-stat"><span>وضعیت اسناد</span><strong>تکمیل</strong></div><div class="shipment-stat"><span>پیشرفت مسیر</span><strong>۶۸٪</strong></div><div class="shipment-stat"><span>زمان باقی‌مانده</span><strong>۲ روز</strong></div></div>
                <div class="float-note"><span><svg viewBox="0 0 24 24" fill="none"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span><span><strong>وضعیت محموله ثبت شد</strong><small>اطلاعات با موفقیت به‌روزرسانی شد</small></span></div>
            </div>
            <div class="visual-footer"><svg viewBox="0 0 24 24" fill="none"><path d="M12 21s7-3 7-9V5l-7-2-7 2v7c0 6 7 9 7 9Z" stroke="currentColor" stroke-width="1.6"/></svg>اطلاعات شما با استانداردهای امنیتی نگهداری می‌شود.</div>
        </div>
    </aside>
</main>
<script>
(()=>{const form=document.getElementById('login-form'),identifier=document.getElementById('identifier'),password=document.getElementById('password'),toggle=document.getElementById('password-toggle'),message=document.getElementById('auth-message'),submit=document.getElementById('submit-button');toggle.addEventListener('click',()=>{const visible=password.type==='text';password.type=visible?'password':'text';toggle.classList.toggle('visible',!visible);toggle.setAttribute('aria-label',visible?'نمایش رمز عبور':'مخفی کردن رمز عبور')});[identifier,password].forEach(input=>input.addEventListener('input',()=>input.closest('.field').classList.remove('invalid')));document.getElementById('forgot-button').addEventListener('click',()=>{message.textContent='برای بازیابی رمز عبور با پشتیبانی سپند در ارتباط باشید.';message.classList.add('show')});form.addEventListener('submit',event=>{event.preventDefault();let valid=true;if(!identifier.value.trim()){document.getElementById('identifier-field').classList.add('invalid');valid=false}if(!password.value){document.getElementById('password-field').classList.add('invalid');valid=false}if(!valid)return;submit.classList.add('loading');setTimeout(()=>{submit.classList.remove('loading');message.textContent='رابط ورود آماده است؛ اتصال نهایی به سرویس احراز هویت انجام نشده است.';message.classList.add('show')},650)})})();
</script>
</body>
</html>
